// Animated click-through demo — the real recorded session.
// Intro title card → raw Playwright take (public/captures/session.webm) with
// chapter caption chips synced to src/Timeline.ts → outro. Timeline.ts is
// generated by scripts/demo-capture.mjs, so re-running the capture keeps the
// edit in sync automatically.
import React from "react";
import {
  AbsoluteFill,
  Easing,
  Sequence,
  interpolate,
  staticFile,
  useCurrentFrame,
  Video,
} from "remotion";
import { DEMO_FPS, OutroCard, TitleCard } from "./Demo";
import { CAPTURE_MS, CHAPTERS } from "./Timeline";

const INTRO_DUR = 96;
const OUTRO_DUR = 100;
const CROSS = 12; // crossfade frames between footage and cards

const capFrames = (ms: number) => Math.round((ms * DEMO_FPS) / 1000);
const CAPTURE_FRAMES = capFrames(CAPTURE_MS);
const VIDEO_FROM = INTRO_DUR - CROSS;
const VIDEO_DUR = CAPTURE_FRAMES;
const OUTRO_FROM = VIDEO_FROM + VIDEO_DUR - CROSS;
export const LIVE_TOTAL = OUTRO_FROM + OUTRO_DUR;

// Footage is exactly 1920×1080 — fills the canvas 1:1.
const TakeClip: React.FC = () => {
  const frame = useCurrentFrame();
  const opacity = Math.min(
    interpolate(frame, [0, CROSS], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }),
    interpolate(frame, [VIDEO_DUR - 10, VIDEO_DUR - 1], [1, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }),
  );
  return (
    <AbsoluteFill style={{ background: "#0d0d0d", opacity }}>
      <Video
        src={staticFile("captures/session.webm")}
        muted
        style={{ width: "100%", height: "100%" }}
      />
    </AbsoluteFill>
  );
};

// Caption chip pinned bottom-left, same language as the screenshot cut.
const ChapterChip: React.FC<{ dur: number; index: number; caption: string }> = ({
  dur,
  index,
  caption,
}) => {
  const frame = useCurrentFrame();
  const y = interpolate(frame, [4, 16], ["14px", "0px"], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const opacity = Math.min(
    interpolate(frame, [4, 14], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.16, 1, 0.3, 1),
    }),
    interpolate(frame, [dur - 8, dur - 1], [1, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }),
  );
  return (
    <div
      style={{
        position: "absolute",
        left: 56,
        bottom: 44,
        opacity,
        transform: `translate(${y})`,
        background: "rgba(21,21,21,0.86)",
        border: "1px solid rgba(255,255,255,0.16)",
        borderRadius: 8,
        padding: "11px 18px",
        fontFamily: "Geist Mono",
        fontSize: 21,
        fontWeight: 500,
        letterSpacing: "0.09em",
        color: "#fafafa",
        whiteSpace: "pre",
      }}
    >
      {`${String(index + 1).padStart(2, "0")} · ${caption.toUpperCase()}`}
    </div>
  );
};

export const OwlasoDemoLive: React.FC = () => {
  const starts = CHAPTERS.map((c) => VIDEO_FROM + capFrames(c.t));
  const chipDurs = starts.map((start, i) =>
    i < starts.length - 1 ? starts[i + 1] - start : OUTRO_FROM - start,
  );
  return (
    <AbsoluteFill style={{ background: "#141414", fontFamily: "Inter, system-ui, sans-serif" }}>
      <Sequence durationInFrames={INTRO_DUR}>
        <TitleCard />
      </Sequence>
      <Sequence from={VIDEO_FROM} durationInFrames={VIDEO_DUR}>
        <TakeClip />
      </Sequence>
      {CHAPTERS.map((chapter, i) => (
        <Sequence
          key={chapter.caption}
          from={starts[i]}
          durationInFrames={chipDurs[i]}
        >
          <ChapterChip dur={chipDurs[i]} index={i} caption={chapter.caption} />
        </Sequence>
      ))}
      <Sequence from={OUTRO_FROM} durationInFrames={OUTRO_DUR}>
        <OutroCard />
      </Sequence>
    </AbsoluteFill>
  );
};
